#include "leave/sensor/sensor_center.h"
#include "net/ros/SensorSelfModel.h"
#include "task/subscribe/zoo_inner_status.h"
#include "BaseThrowable.h"
#include "manager/PublishInnerManager.h"
#include "future/node/motor_server.h"
#include "manager/PublishOutManager.h"

void SensorCenter::initialize(const ros::NodeHandle &handle) {
    sensorSelfMode = false;

    sensors.push_back(std::make_shared<Carpet>(handle));
    sensors.push_back(std::make_shared<Collision>(handle));
    sensors.push_back(std::make_shared<Imu>(handle));
    sensors.push_back(std::make_shared<Metal>(handle));
    sensors.push_back(std::make_shared<Odometer>(handle));
    sensors.push_back(std::make_shared<Radar>(handle));
    sensors.push_back(std::make_shared<SilverBullUp>(handle));
    sensors.push_back(std::make_shared<SilverBullDown>(handle));
    sensors.push_back(std::make_shared<TofLeft>(handle));
    sensors.push_back(std::make_shared<TofRight>(handle));
    sensors.push_back(std::make_shared<Ultrasonic1>(handle));
    sensors.push_back(std::make_shared<Ultrasonic2>(handle));
    sensors.push_back(std::make_shared<Ultrasonic3>(handle));
    sensors.push_back(std::make_shared<Ultrasonic4>(handle));

    polymerization_thread = std::thread(&SensorCenter::sensor_polymerization_thread_func, this);
    polymerization_thread.detach();
}

bool SensorCenter::isSensorSelfMode() {
    return sensorSelfMode;
}

void SensorCenter::startInspect() {
    if (!ZooInnerStatus::instance().getIsCharging()) {
        throw app::exception(make_error_code(error::please_ensure_to_start_end_the_self_at_the_base_station));
    }
    if (ZooInnerStatus::instance().getUrgencyStopStatus()) {
        throw app::exception(make_error_code(error::please_ensure_to_start_end_the_self_non_emergency_stop_status));
    }

    std_msgs::Int32 map_start;
    map_start.data = 2;
    PublishInnerManager::instance().publishManualPush(map_start);

    MotorServerSingleton::instance().start();
    MotorServerSingleton::instance().startInu();

    if (!sensorSelfMode) {
        sensorSelfMode = true;
        for (const auto &sensor: sensors) {
            sensor->startInspect();
        }
    }
}

void SensorCenter::stopInspect() {
    if (!ZooInnerStatus::instance().getIsCharging()) {
        throw app::exception(make_error_code(error::the_map_needs_to_be_saved_at_the_base_station_location));
    }

    std_msgs::Int32 map_start;
    map_start.data = 0;
    PublishInnerManager::instance().publishManualPush(map_start);

    MotorServerSingleton::instance().stop();
    MotorServerSingleton::instance().stopInu();

//    if (sensorSelfMode) {
    sensorSelfMode = false;
    for (const auto &sensor: sensors) {
        sensor->stopInspect();
    }
//    }
}

void SensorCenter::sensor_polymerization_thread_func() {
    while (true) {
        if (sensorSelfMode) {
            SensorSelf self(carpetData, collisionData, imuData, metalData, odomData,
                            scanData, silverUpData, silverDownData,
                            tofLeftData, tofRightData, ultrasonic1Data,
                            ultrasonic2Data, ultrasonic3Data, ultrasonic4Data);

            PublishOutManager::instance().publishSensorCheck(self);
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }
}

